(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,7150,(e,t,s)=>{t.exports=[{slug:"testing-theory",order:1,status:"published",translations:{uk:{title:"Теорія тестування",description:"Фундамент QA: принципи, процес, вимоги, рівні й типи тестування, документація, дефекти, ризики та release readiness."},en:{title:"Testing theory",description:"QA foundations: principles, process, requirements, testing levels and types, documentation, defects, risk, and release readiness."}}},{slug:"test-design",order:2,status:"published",translations:{uk:{title:"Тест-дизайн",description:"Техніки проєктування перевірок, моделювання ризиків і побудова корисного тестового покриття."},en:{title:"Test design",description:"Test design techniques, risk modelling, and building useful test coverage."}}},{slug:"automation-architecture",order:3,status:"published",translations:{uk:{title:"Архітектура автоматизації",description:"Структура тестових фреймворків, межі шарів, підтримуваність і надійні сигнали якості."},en:{title:"Automation architecture",description:"Test framework structure, layer boundaries, maintainability, and reliable quality signals."}}},{slug:"python-coding-whiteboard",order:4,status:"published",translations:{uk:{title:"Python і Coding Whiteboard",description:"Python для QA, алгоритмічне мислення та практичні задачі для технічних співбесід."},en:{title:"Python and Coding Whiteboard",description:"Python for QA, algorithmic thinking, and practical technical interview exercises."}}},{slug:"typescript-playwright-bdd",order:5,status:"published",translations:{uk:{title:"TypeScript, Playwright і BDD",description:"Типобезпечна автоматизація web, патерни Playwright і прагматичне застосування BDD."},en:{title:"TypeScript, Playwright and BDD",description:"Type-safe web automation, Playwright patterns, and pragmatic BDD."}}},{slug:"web-http-networking",order:6,status:"published",translations:{uk:{title:"Web, HTTP і мережі",description:"Як браузер, протоколи та мережеві шари впливають на поведінку й тестованість системи."},en:{title:"Web, HTTP and networking",description:"How browsers, protocols, and network layers affect system behaviour and testability."}}},{slug:"api-sql-data",order:7,status:"published",translations:{uk:{title:"API, SQL і дані",description:"Контракти API, робота з базами даних, цілісність даних і перевірки інтеграцій."},en:{title:"API, SQL and data",description:"API contracts, database work, data integrity, and integration testing."}}},{slug:"cicd-docker-kubernetes",order:8,status:"published",translations:{uk:{title:"CI/CD, Docker і Kubernetes",description:"Пайплайни, контейнери, оркестрація та швидкий зворотний зв’язок від перевірок."},en:{title:"CI/CD, Docker and Kubernetes",description:"Pipelines, containers, orchestration, and fast feedback from quality checks."}}},{slug:"security-devsecops",order:9,status:"published",translations:{uk:{title:"Security і DevSecOps",description:"Моделювання загроз, безпекові перевірки та інтеграція security-практик у delivery."},en:{title:"Security and DevSecOps",description:"Threat modelling, security testing, and integrating security practices into delivery."}}},{slug:"system-design-cloud",order:10,status:"published",translations:{uk:{title:"System Design і Cloud",description:"Компоненти розподілених систем, компроміси архітектури та тестування хмарних рішень."},en:{title:"System Design and Cloud",description:"Distributed system components, architecture trade-offs, and testing cloud solutions."}}},{slug:"ai-llm-rag-agents",order:11,status:"published",translations:{uk:{title:"AI, LLM, RAG і агенти",description:"Будова LLM-рішень, retrieval-архітектури, агенти та їх практичне тестування."},en:{title:"AI, LLM, RAG and agents",description:"LLM solution design, retrieval architectures, agents, and their practical testing."}}},{slug:"llmops-evaluation-observability",order:12,status:"published",translations:{uk:{title:"LLMOps, Evaluation і Observability",description:"Оцінювання якості LLM, експерименти, моніторинг і контроль поведінки AI-систем."},en:{title:"LLMOps, Evaluation and Observability",description:"LLM quality evaluation, experiments, monitoring, and control of AI system behaviour."}}}]},4555,(e,t,s)=>{t.exports=JSON.parse('[{"id":"purpose-of-testing","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що таке тестування програмного забезпечення і навіщо воно потрібне?","answer":"Тестування — це систематичне дослідження продукту та пов’язаної документації, яке допомагає знаходити дефекти, перевіряти очікувану поведінку й давати команді інформацію про якість і ризики. Його мета — не «довести, що все працює», а зменшити невизначеність перед рішенням.","examples":["Для сервісу переказів недостатньо побачити успішний платіж: команда також має знати, як система поводиться при повторному запиті, відмові банку та втраті мережі."],"exercises":["Оберіть знайомий продукт і сформулюйте три рішення, для яких результати тестування можуть дати корисну інформацію."]},"en":{"question":"What is software testing, and why do we need it?","answer":"Testing is the systematic investigation of a product and its related documentation to reveal defects, check expected behaviour, and give the team information about quality and risk. Its purpose is not to “prove everything works,” but to reduce uncertainty before a decision.","examples":["For a money-transfer service, a successful payment is not enough: the team also needs evidence about repeated requests, bank declines, and network loss."],"exercises":["Choose a familiar product and describe three decisions that testing evidence could support."]}}},{"id":"exhaustive-testing","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чому повне, або exhaustive, тестування майже завжди неможливе?","answer":"Кількість комбінацій даних, станів, конфігурацій і шляхів виконання дуже швидко стає практично нескінченною. Тому тестування завжди є вибіркою: ми визначаємо пріоритети за ризиком, застосовуємо техніки тест-дизайну й чесно описуємо, що залишилося неперевіреним.","examples":["Навіть поле з десятьма символами має величезну кількість можливих значень, а разом із браузерами, ролями та станами системи простір перевірок зростає ще більше."],"exercises":["Для форми входу перелічіть виміри тестового простору й поясніть, як скоротите їх без випадкового вибору."]},"en":{"question":"Why is exhaustive testing almost always impossible?","answer":"The number of data combinations, states, configurations, and execution paths quickly becomes impractically large. Testing is therefore a sample: we prioritise by risk, apply test-design techniques, and clearly communicate what remains untested.","examples":["Even a ten-character field allows an enormous number of values; adding browsers, roles, and system states expands the test space further."],"exercises":["For a sign-in form, list the dimensions of the test space and explain how you would reduce them deliberately."]}}},{"id":"qa-qc-testing","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Як пов’язані Quality Assurance, Quality Control і тестування?","answer":"Quality Assurance працює з процесами, які мають запобігати проблемам; Quality Control оцінює властивості створеного продукту; тестування є одним зі способів такого оцінювання. Межі термінів залежать від організації, тому важливіше узгодити відповідальність і очікуваний результат, ніж сперечатися про назви.","examples":["Рев’ю Definition of Done належить до профілактики процесу, а перевірка готового API-контракту — до контролю продукту."],"exercises":["Розподіліть п’ять дій вашої команди між запобіганням дефектам, оцінюванням продукту та тестовим виконанням."]},"en":{"question":"How are Quality Assurance, Quality Control, and testing related?","answer":"Quality Assurance focuses on processes intended to prevent problems; Quality Control evaluates properties of the product that was built; testing is one way to perform that evaluation. Terminology varies by organisation, so agreed responsibilities and outcomes matter more than labels.","examples":["Reviewing the Definition of Done is process prevention, while checking an implemented API contract is product control."],"exercises":["Classify five team activities as defect prevention, product evaluation, or test execution."]}}},{"id":"verification-validation","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чим verification відрізняється від validation?","answer":"Verification перевіряє, чи правильно реалізовано погоджені вимоги, дизайн або контракт. Validation з’ясовує, чи розв’язує продукт реальну потребу користувача. Реалізація може точно відповідати специфікації й водночас бути незручною або непотрібною.","examples":["Форма приймає рівно 20 символів, як вимагає специфікація, але реальні ідентифікатори клієнтів мають 24 символи."],"exercises":["Для checkout наведіть окремий приклад verification і validation та визначте, хто може надати oracle."]},"en":{"question":"How does verification differ from validation?","answer":"Verification checks whether agreed requirements, designs, or contracts were implemented correctly. Validation asks whether the product solves the user’s real need. An implementation can match the specification exactly and still be inconvenient or useless.","examples":["A form accepts exactly 20 characters as specified, but real customer identifiers contain 24 characters."],"exercises":["For a checkout, give one verification and one validation example and identify who can provide the oracle."]}}},{"id":"testing-principles","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Які базові принципи допомагають реалістично планувати тестування?","answer":"Тестування показує наявність проблем, але не гарантує їх відсутності; повна перевірка недосяжна; ранній зворотний зв’язок дешевший; дефекти часто концентруються в окремих зонах; повторення одного набору з часом втрачає ефективність; підхід залежить від контексту. Навіть продукт без відомих дефектів може не задовольняти користувача.","examples":["Стабільний regression suite роками проходить зелено, але не перевіряє новий мобільний сценарій, яким користується більшість клієнтів."],"exercises":["Оберіть два принципи й опишіть рішення, яке зміниться, якщо команда справді застосує їх у наступному релізі."]},"en":{"question":"Which principles help us plan testing realistically?","answer":"Testing can reveal problems but cannot guarantee their absence; exhaustive coverage is unattainable; earlier feedback is cheaper; defects often cluster; repeating the same set loses effectiveness over time; and the approach depends on context. A product with no known defects may still fail its users.","examples":["A stable regression suite stays green for years but does not cover a new mobile journey used by most customers."],"exercises":["Choose two principles and describe a release decision that would change if the team applied them seriously."]}}},{"id":"test-lifecycle","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"З яких активностей складається життєвий цикл тестування?","answer":"Практичний цикл охоплює аналіз вимог і ризиків, планування, проєктування перевірок, підготовку середовища та даних, виконання, роботу з дефектами, повторні й регресійні перевірки, звітність і завершення. Це не обов’язково лінійні фази: в ітеративній розробці вони перекриваються та повторюються.","examples":["Під час аналізу нового refund workflow команда одночасно уточнює вимоги, готує API fixtures і визначає сигнали для production monitoring."],"exercises":["Намалюйте цикл тестування для невеликої зміни API та позначте входи, результати й відповідальних за кожну активність."]},"en":{"question":"Which activities make up a testing lifecycle?","answer":"A practical lifecycle covers requirement and risk analysis, planning, test design, environment and data preparation, execution, defect work, retesting and regression, reporting, and closure. These are not necessarily linear phases: iterative development makes them overlap and repeat.","examples":["While analysing a new refund workflow, the team also clarifies requirements, prepares API fixtures, and defines production monitoring signals."],"exercises":["Draw the testing lifecycle for a small API change and mark the inputs, outputs, and owners of each activity."]}}},{"id":"requirements-quality","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Які властивості роблять вимогу тестованою та корисною?","answer":"Якісна вимога має бути зрозумілою, однозначною, несуперечливою, повною в потрібних межах, здійсненною, актуальною, пріоритезованою, трасованою й такою, що допускає перевірку. Формальний шаблон не рятує вимогу, якщо команда не може визначити спостережуваний результат.","examples":["«Сторінка має завантажуватися швидко» не дає oracle; «p95 до 2 секунд при 500 активних користувачах у визначеному середовищі» вже можна перевірити."],"exercises":["Візьміть нечітку вимогу й перепишіть її так, щоб з’явилися умови, спостережуваний результат і межі."]},"en":{"question":"What makes a requirement testable and useful?","answer":"A good requirement should be understandable, unambiguous, consistent, sufficiently complete, feasible, current, prioritised, traceable, and verifiable. A formal template does not help when the team cannot identify an observable outcome.","examples":["“The page must load quickly” provides no oracle; “p95 below two seconds for 500 active users in the defined environment” can be tested."],"exercises":["Take a vague requirement and rewrite it with conditions, an observable result, and explicit boundaries."]}}},{"id":"static-dynamic","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чим static testing відрізняється від dynamic testing?","answer":"Static testing аналізує артефакти без виконання програмного коду: вимоги, дизайн, схеми, код або тестові сценарії. Dynamic testing спостерігає поведінку системи під час виконання. Обидва підходи доповнюють один одного й знаходять різні класи проблем.","examples":["Review OpenAPI знаходить суперечливі типи до запуску сервісу, а API test показує фактичну обробку запиту в runtime."],"exercises":["Для нової функції запропонуйте три static і три dynamic перевірки та поясніть очікувані findings."]},"en":{"question":"How does static testing differ from dynamic testing?","answer":"Static testing analyses artefacts without executing application code: requirements, designs, schemas, code, or test scenarios. Dynamic testing observes the running system’s behaviour. The two approaches complement each other and reveal different classes of problems.","examples":["An OpenAPI review finds inconsistent types before the service runs, while an API test shows the actual request handling at runtime."],"exercises":["For a new feature, propose three static and three dynamic checks and explain the findings you expect."]}}},{"id":"black-white-grey-box","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що означають black-box, white-box і grey-box testing?","answer":"Black-box перевірки спираються на зовнішню поведінку без знання реалізації. White-box використовує структуру коду, гілки або внутрішні потоки. Grey-box поєднує зовнішній сценарій з частковим знанням архітектури чи даних. Це способи бачити систему, а не окремі рівні тестування.","examples":["UI-сценарій може бути black-box, unit test гілок розрахунку — white-box, а API-перевірка з контролем запису в базі — grey-box."],"exercises":["Для одного checkout-сценарію спроєктуйте по одній перевірці з кожної перспективи."]},"en":{"question":"What do black-box, white-box, and grey-box testing mean?","answer":"Black-box checks focus on external behaviour without implementation knowledge. White-box testing uses code structure, branches, or internal flows. Grey-box testing combines an external scenario with partial knowledge of architecture or data. These are perspectives on a system, not separate test levels.","examples":["A UI journey may be black-box, a unit test of calculation branches white-box, and an API check with database verification grey-box."],"exercises":["For one checkout scenario, design one check from each perspective."]}}},{"id":"test-levels","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чим відрізняються component, integration, system і acceptance testing?","answer":"Component testing ізолює невелику одиницю; integration перевіряє взаємодію частин; system розглядає повну систему відносно вимог; acceptance оцінює готовність задовольнити бізнесову або користувацьку потребу. Межі залежать від архітектури, тому їх потрібно визначати для конкретного продукту.","examples":["Функція розрахунку податку, обмін checkout із tax service, повна покупка та бізнесове приймання бухгалтерією — це різні рівні одного ризику."],"exercises":["Розкладіть один критичний ризик вашого продукту на перевірки чотирьох рівнів без дублювання однакових деталей."]},"en":{"question":"How do component, integration, system, and acceptance testing differ?","answer":"Component testing isolates a small unit; integration testing checks interactions among parts; system testing evaluates the complete system against requirements; acceptance testing assesses readiness to satisfy a business or user need. Boundaries depend on architecture and must be defined for the product.","examples":["A tax calculation function, checkout-to-tax-service interaction, a complete purchase, and accounting acceptance represent different levels of one risk."],"exercises":["Map one critical product risk to checks at all four levels without duplicating the same details."]}}},{"id":"functional-nonfunctional","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Чим functional testing відрізняється від non-functional testing?","answer":"Functional testing перевіряє, що система робить: правила, обчислення, переходи та результати. Non-functional testing досліджує, як система це робить: продуктивність, надійність, безпеку, доступність, сумісність та інші характеристики. Один сценарій часто потребує обох перспектив.","examples":["Пошук повертає правильні товари — функціональна перевірка; відповідь пошуку вкладається в latency budget під навантаженням — нефункціональна."],"exercises":["Для завантаження файлу сформулюйте три functional і три non-functional ризики."]},"en":{"question":"How does functional testing differ from non-functional testing?","answer":"Functional testing checks what the system does: rules, calculations, transitions, and outcomes. Non-functional testing investigates how it does so: performance, reliability, security, accessibility, compatibility, and other characteristics. One journey often needs both perspectives.","examples":["Search returning the correct products is functional; staying within the latency budget under load is non-functional."],"exercises":["For a file upload, define three functional and three non-functional risks."]}}},{"id":"positive-negative","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що відрізняє positive і negative testing?","answer":"Positive testing перевіряє очікуване використання з допустимими даними. Negative testing досліджує помилкові, неочікувані або заборонені умови й те, чи система безпечно їх обробляє. Negative не означає хаотично вводити «щось неправильне» — сценарій має походити з конкретного ризику.","examples":["Для промокоду positive test використовує активний код у межах правил, а negative — прострочений код, повторне застосування або змінену роль користувача."],"exercises":["Для відновлення пароля створіть три positive і п’ять risk-based negative сценаріїв."]},"en":{"question":"What distinguishes positive and negative testing?","answer":"Positive testing checks expected use with valid data. Negative testing explores invalid, unexpected, or forbidden conditions and whether the system handles them safely. Negative does not mean entering random bad values; each scenario should come from a specific risk.","examples":["For a promo code, a positive test uses an active code within its rules; negative tests cover expiry, reuse, or a changed user role."],"exercises":["Create three positive and five risk-based negative scenarios for password recovery."]}}},{"id":"smoke-sanity-retest-regression","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Як не плутати smoke, sanity, retest і regression?","answer":"Smoke швидко перевіряє, чи збірка придатна для глибшого тестування. Sanity вузько підтверджує узгоджену область після зміни. Retest повторює сценарій конкретного дефекту. Regression шукає небажані наслідки зміни в пов’язаній поведінці. Назви можуть відрізнятися між командами, тому scope має бути явним.","examples":["Після виправлення знижки retest повторює помилковий розрахунок, regression охоплює податок і оплату, а smoke спершу перевіряє, що checkout узагалі відкривається."],"exercises":["Для одного bug fix визначте окремий scope чотирьох наборів і поясніть, які з них можна автоматизувати."]},"en":{"question":"How can we distinguish smoke, sanity, retesting, and regression?","answer":"Smoke testing quickly checks whether a build is suitable for deeper testing. Sanity narrowly confirms an agreed area after a change. Retesting repeats the scenario of a specific defect. Regression looks for unintended effects in related behaviour. Teams use the labels differently, so scope must be explicit.","examples":["After a discount fix, retesting repeats the failed calculation, regression covers tax and payment, while smoke first confirms that checkout opens at all."],"exercises":["For one bug fix, define separate scopes for all four sets and explain which ones should be automated."]}}},{"id":"risk-based-testing","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Як risk-based testing допомагає визначити пріоритет?","answer":"Команда пов’язує глибину й порядок перевірок з імовірністю проблеми та силою її впливу, враховуючи складність зміни, історію дефектів, критичність даних, спостережуваність і вартість відновлення. Це не магічна формула, а прозорий спосіб обговорювати обмеження.","examples":["Невелика зміна формату рахунку може мати високий ризик, якщо документ потрібен для податкової звітності багатьох клієнтів."],"exercises":["Побудуйте risk matrix для трьох змін одного релізу й назвіть сигнал, який змусить переглянути кожну оцінку."]},"en":{"question":"How does risk-based testing help set priorities?","answer":"The team connects testing depth and order to the likelihood and impact of a problem while considering change complexity, defect history, data criticality, observability, and recovery cost. It is not a magic formula but a transparent way to discuss constraints.","examples":["A small invoice-format change may carry high risk when many customers need that document for tax reporting."],"exercises":["Build a risk matrix for three release changes and name one signal that would make you revise each assessment."]}}},{"id":"checklist-vs-test-case","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Коли достатньо checklist, а коли потрібен детальний test case?","answer":"Checklist компактно фіксує ідеї перевірок і добре працює для досвідченої команди та мінливого продукту. Детальний test case корисний, коли потрібні повторюваність, передавання знань, аудит або складні дані й очікування. Формат обирають за ціною неоднозначності, а не за звичкою.","examples":["Короткий список браузерних ризиків може бути checklist, а регульований фінансовий сценарій із точними preconditions і expected results — test case."],"exercises":["Візьміть один сценарій і створіть checklist та test case; порівняйте час підготовки й ризик різного трактування."]},"en":{"question":"When is a checklist enough, and when is a detailed test case needed?","answer":"A checklist compactly captures test ideas and works well for an experienced team and a changing product. A detailed test case helps when repeatability, knowledge transfer, auditability, or complex data and expectations matter. Choose the format by the cost of ambiguity, not habit.","examples":["A short list of browser risks may be a checklist, while a regulated financial flow with exact preconditions and expected results needs a test case."],"exercises":["Represent one scenario as both a checklist and a test case; compare preparation time and interpretation risk."]}}},{"id":"effective-test-case","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Що робить test case справді корисним?","answer":"Корисний test case має зрозумілу мету, контрольовані передумови й дані, однозначні дії, спостережуваний очікуваний результат і зв’язок із ризиком або вимогою. Він має бути достатньо детальним для своєї аудиторії, але не дублювати очевидне й не приховувати oracle у довгому тексті.","examples":["«Перевірити оплату» не пояснює успіх; очікування про статус замовлення, списання, подію та повторний запит роблять перевірку діагностичною."],"exercises":["Відредагуйте слабкий test case: приберіть зайві UI-деталі, додайте дані, oracle та postconditions."]},"en":{"question":"What makes a test case genuinely useful?","answer":"A useful test case has a clear purpose, controlled preconditions and data, unambiguous actions, an observable expected result, and a link to a risk or requirement. It should be detailed enough for its audience without restating the obvious or hiding the oracle in long prose.","examples":["“Test payment” does not define success; expectations for order state, charge, event, and retry behaviour make the check diagnostic."],"exercises":["Edit a weak test case: remove incidental UI detail and add data, an oracle, and postconditions."]}}},{"id":"defect-failure-root-cause","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Чим відрізняються error, defect, failure і root cause?","answer":"Error — людська помилка або неправильне рішення; defect — вада в артефакті чи коді; failure — спостережуване відхилення системи під час виконання; root cause — глибинна причина, що дозволила проблемі виникнути або пройти далі. Один failure може мати кілька причин, а defect може довго не проявлятися.","examples":["Неправильно зрозуміле правило призвело до дефектної умови в коді; failure видно лише для певної валюти, а root cause включає нечітку вимогу й відсутнє review."],"exercises":["Для відомого production incident побудуйте ланцюг error → defect → failure → contributing causes."]},"en":{"question":"How do error, defect, failure, and root cause differ?","answer":"An error is a human mistake or incorrect decision; a defect is a flaw in an artefact or code; a failure is an observable deviation while the system runs; a root cause is an underlying condition that allowed the problem to occur or escape. One failure may have several causes, and a defect may remain dormant.","examples":["A misunderstood rule produced a faulty condition in code; the failure appears only for one currency, while root causes include a vague requirement and missing review."],"exercises":["For a known production incident, map error → defect → failure → contributing causes."]}}},{"id":"defect-report","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Які дані потрібні в якісному defect report?","answer":"Звіт має дозволити зрозуміти, відтворити й оцінити проблему: короткий фактичний заголовок, версія та середовище, передумови й дані, мінімальні кроки, actual і expected result, стабільність відтворення, вплив, докази та пов’язані артефакти. Severity описує наслідок, priority — терміновість рішення.","examples":["Замість «оплата не працює» корисний заголовок називає умову, місце й результат: «Повторний POST створює друге списання після timeout відповіді»."],"exercises":["Перепишіть нечіткий bug report так, щоб інша людина могла відтворити проблему без усного пояснення."]},"en":{"question":"What information belongs in a good defect report?","answer":"A report should let others understand, reproduce, and assess the problem: a factual summary, version and environment, preconditions and data, minimal steps, actual and expected results, reproducibility, impact, evidence, and related artefacts. Severity describes impact; priority describes urgency.","examples":["Instead of “payment is broken,” a useful summary names condition, location, and outcome: “Repeated POST creates a second charge after response timeout.”"],"exercises":["Rewrite a vague bug report so another person can reproduce the problem without verbal context."]}}},{"id":"severity-priority","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Чому severity і priority не можна зводити до одного поля?","answer":"Severity оцінює масштаб і характер впливу дефекту на продукт, користувача або дані. Priority відображає бізнесову черговість виправлення з урахуванням дедлайнів, охоплення, workaround і вартості. Висока severity не завжди означає перше виправлення, а низька severity може мати терміновий бізнесовий контекст.","examples":["Рідкісний crash адміністративного інструмента може мати високу severity, але нижчий priority; помилка в тексті на головній сторінці перед кампанією — навпаки."],"exercises":["Наведіть чотири комбінації high/low severity та priority і обґрунтуйте їх контекстом."]},"en":{"question":"Why should severity and priority remain separate?","answer":"Severity estimates the scale and nature of a defect’s impact on the product, user, or data. Priority represents business repair order considering deadlines, reach, workarounds, and cost. High severity does not always mean first to fix, while a low-severity issue can be urgent in its business context.","examples":["A rare crash in an admin tool may have high severity but lower priority; a homepage typo before a campaign can show the opposite pattern."],"exercises":["Provide four high/low severity and priority combinations and justify each with context."]}}},{"id":"test-basis-oracle","direction":"testing-theory","level":"Junior","translations":{"uk":{"question":"Що таке test basis і test oracle?","answer":"Test basis — це джерела, з яких ми виводимо умови перевірки: вимоги, контракти, моделі, ризики, закони або фактичну поведінку попередньої версії. Test oracle — спосіб визначити очікуваний результат. Oracle може походити зі специфікації, бізнес-правила, еталонної системи, обчислення чи думки експерта, але його надійність теж потрібно оцінювати.","examples":["Для розрахунку знижки test basis містить правила програми лояльності, а oracle може бути незалежним розрахунком очікуваної суми."],"exercises":["Для знайомої функції перелічіть доступні test basis, оберіть oracle і вкажіть, де він може помилятися."]},"en":{"question":"What are a test basis and a test oracle?","answer":"A test basis is the set of sources from which we derive test conditions: requirements, contracts, models, risks, laws, or the observed behaviour of an earlier version. A test oracle is the means used to determine the expected result. It may come from a specification, business rule, reference system, calculation, or expert judgement, and its reliability must also be assessed.","examples":["For a discount calculation, the loyalty-program rules form the test basis, while an independent calculation can serve as the oracle."],"exercises":["For a familiar feature, list the available test basis, choose an oracle, and identify how that oracle could be wrong."]}}},{"id":"traceability-coverage","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Навіщо потрібна трасованість між вимогами, ризиками та перевірками?","answer":"Трасованість показує, які вимоги й ризики покриті перевірками, які результати та дефекти з ними пов’язані, а де залишилися прогалини. Це не обов’язково велика RTM-таблиця: зв’язки можуть жити в test management, issue tracker або коді. Важлива можливість відповісти, що саме перевірено і яким evidence це підтверджено.","examples":["Посилання requirement → API test → запуск CI → defect дозволяє побачити не лише наявність тесту, а й актуальний результат та відому проблему."],"exercises":["Побудуйте мінімальну traceability map для трьох вимог і перевірте, чи є вимога без тесту або тест без зрозумілої мети."]},"en":{"question":"Why do we need traceability between requirements, risks, and tests?","answer":"Traceability shows which requirements and risks are covered by checks, which results and defects relate to them, and where gaps remain. It does not have to be a large RTM spreadsheet: links may live in test management, an issue tracker, or code. What matters is being able to explain what was checked and which evidence supports it.","examples":["A requirement → API test → CI run → defect chain shows not only that a test exists, but also its current result and a known problem."],"exercises":["Build a minimal traceability map for three requirements and look for a requirement without a test or a test without a clear purpose."]}}},{"id":"test-environment-data","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Чому тестове середовище й дані є частиною дизайну перевірок?","answer":"Результат залежить не лише від кроків тесту, а й від версій сервісів, конфігурації, інтеграцій, доступів, часу та стану даних. Контрольоване середовище підвищує відтворюваність, а репрезентативні дані допомагають побачити реальні ризики. Водночас тестові дані мають відповідати правилам приватності й безпеки.","examples":["Refund test може проходити на stub, але падати зі справжнім payment sandbox через інший timeout і повторну доставку webhook."],"exercises":["Для одного integration test складіть перелік залежностей, конфігурацій і даних, які потрібно контролювати або фіксувати в evidence."]},"en":{"question":"Why are test environments and data part of test design?","answer":"A result depends not only on test steps but also on service versions, configuration, integrations, access, time, and data state. A controlled environment improves reproducibility, while representative data helps expose realistic risks. Test data must also comply with privacy and security rules.","examples":["A refund test may pass against a stub but fail with the real payment sandbox because of a different timeout and webhook redelivery."],"exercises":["For one integration test, list the dependencies, configurations, and data that must be controlled or recorded as evidence."]}}},{"id":"entry-exit-criteria","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Що дають entry, exit і suspension criteria?","answer":"Entry criteria визначають, коли тестову активність має сенс починати; exit criteria — який evidence потрібен для її завершення або рішення; suspension criteria — коли продовження не дає надійного результату чи марнує ресурс. Це орієнтири для рішення, а не автоматична гарантія якості.","examples":["Якщо середовище нестабільне й половина API-запитів падає через інфраструктуру, suspension criterion захищає команду від фальшивих висновків."],"exercises":["Сформулюйте entry, exit і suspension criteria для короткого regression cycle та додайте відповідального за винятки."]},"en":{"question":"What do entry, exit, and suspension criteria provide?","answer":"Entry criteria define when a test activity is ready to start; exit criteria define the evidence needed to finish it or make a decision; suspension criteria define when continuing would produce unreliable results or waste resources. They guide decisions rather than automatically guaranteeing quality.","examples":["If the environment is unstable and half of the API requests fail because of infrastructure, a suspension criterion prevents the team from drawing false conclusions."],"exercises":["Define entry, exit, and suspension criteria for a short regression cycle and name the owner of exceptions."]}}},{"id":"defect-lifecycle","direction":"testing-theory","level":"Middle","translations":{"uk":{"question":"Що описує життєвий цикл дефекту?","answer":"Життєвий цикл дефекту описує стани й рішення від реєстрації до закриття: triage, призначення, виправлення, перевірку, повторне відкриття, відкладення або відхилення. Конкретні назви залежать від команди. Важливі чіткі переходи, відповідальність і причина рішення, а не максимальна кількість статусів.","examples":["Після статусу Fixed перевірка підтверджує початковий сценарій, але regression знаходить побічний ефект: це може бути reopen або окремий defect за правилами команди."],"exercises":["Намалюйте мінімальний defect workflow для своєї команди й визначте, хто та на основі якого evidence виконує кожен перехід."]},"en":{"question":"What does a defect lifecycle describe?","answer":"A defect lifecycle describes states and decisions from reporting to closure: triage, assignment, fixing, verification, reopening, deferral, or rejection. Exact labels vary by team. Clear transitions, ownership, and reasons for decisions matter more than having many statuses.","examples":["After a defect is marked Fixed, verification confirms the original scenario but regression reveals a side effect; team policy determines whether to reopen it or report a separate defect."],"exercises":["Draw a minimal defect workflow for your team and define who performs each transition and which evidence supports it."]}}},{"id":"test-strategy","direction":"testing-theory","level":"Senior","translations":{"uk":{"question":"Що має пояснювати test strategy?","answer":"Стратегія пов’язує цілі якості й продуктові ризики з рівнями, типами та техніками тестування. Вона визначає scope і виключення, середовища, дані, automation approach, ролі, evidence, критерії входу й виходу, звітність та реакцію на findings. Це модель рішень, а не шаблон документа заради документа.","examples":["Для платіжної функції стратегія може перенести більшість контрактних перевірок на API-рівень, залишити кілька критичних UI journeys і додати production signals."],"exercises":["Створіть односторінкову стратегію для зміни з трьома головними ризиками та поясніть, що свідомо не тестуватимете."]},"en":{"question":"What should a test strategy explain?","answer":"A strategy connects quality goals and product risks to testing levels, types, and techniques. It defines scope and exclusions, environments, data, automation approach, roles, evidence, entry and exit criteria, reporting, and responses to findings. It is a decision model, not a document template for its own sake.","examples":["For a payment feature, the strategy may place most contract checks at API level, retain a few critical UI journeys, and add production signals."],"exercises":["Create a one-page strategy for a change with three major risks and explain what you will deliberately not test."]}}},{"id":"release-readiness","direction":"testing-theory","level":"Senior","translations":{"uk":{"question":"Як оцінювати release readiness без магічного відсотка pass rate?","answer":"Готовність до релізу — це рішення на основі evidence: покриття критичних ризиків, стан важливих дефектів, результати перевірок і review, стабільність середовища, якість даних, відомі обмеження, observability, rollback і відповідальність за прийняття ризику. Pass rate корисний лише разом із контекстом набору.","examples":["99% green може приховувати єдиний провалений сценарій повернення коштів, тоді як 90% із падіннями неактуальних low-risk тестів може не блокувати реліз."],"exercises":["Підготуйте короткий release recommendation із фактами, невизначеністю, залишковими ризиками та явним decision owner."]},"en":{"question":"How can release readiness be assessed without a magic pass-rate threshold?","answer":"Release readiness is a decision based on evidence: coverage of critical risks, important defect status, test and review outcomes, environment stability, data quality, known limitations, observability, rollback, and ownership of risk acceptance. Pass rate is useful only with the context of the test set.","examples":["A 99% green result may hide the one failed refund journey, while 90% with obsolete low-risk failures may not block release."],"exercises":["Prepare a short release recommendation containing facts, uncertainty, residual risks, and an explicit decision owner."]}}},{"id":"metrics-context","direction":"testing-theory","level":"Senior","translations":{"uk":{"question":"Які тестові метрики допомагають, а які вводять в оману?","answer":"Метрика корисна, коли підтримує конкретне рішення й має зрозумілий знаменник та контекст. Тренд escaped defects, час зворотного зв’язку або покриття визначених ризиків можуть показати проблему. Кількість test cases, знайдених дефектів чи automation percentage без контексту легко перетворюються на vanity metrics і стимулюють неправильну поведінку.","examples":["Зростання кількості тестів нічого не доводить, якщо suite триває довше, частіше flaky й не знаходить критичних regressions."],"exercises":["Оберіть три метрики вашої команди й для кожної запишіть рішення, обмеження та можливий спосіб маніпуляції."]},"en":{"question":"Which testing metrics help, and which mislead?","answer":"A metric is useful when it supports a specific decision and has a clear denominator and context. Trends in escaped defects, feedback time, or coverage of defined risks may expose a problem. Counts of test cases, defects, or automation percentage without context easily become vanity metrics and encourage harmful behaviour.","examples":["A growing test count proves little when the suite becomes slower, flakier, and still misses critical regressions."],"exercises":["Choose three team metrics and document the decision, limitation, and possible gaming behaviour for each."]}}}]')},2400,(e,t,s)=>{t.exports=JSON.parse('[{"id":"equivalence-partitioning","direction":"test-design","translations":{"uk":{"question":"Навіщо equivalence partitioning?","answer":"Ділить вхідні дані на класи з очікувано однаковою поведінкою, щоб зменшити кількість перевірок.","examples":["Поле віку 18–65 можна перевірити представниками валідного класу та класів нижче і вище меж."],"exercises":["Для правила кількості 1–99 визнач класи еквівалентності й вибери представників."]},"en":{"question":"Why use equivalence partitioning?","answer":"It divides input data into classes expected to behave alike, reducing the number of checks.","examples":["For an age field accepting 18–65, test representatives of the valid class and the classes below and above the limits."],"exercises":["For a quantity rule of 1–99, identify equivalence classes and choose representatives."]}}},{"id":"decision-table","direction":"test-design","translations":{"uk":{"question":"Коли потрібна decision table?","answer":"Коли результат залежить від комбінацій умов і бізнес-правил.","examples":["Знижка може залежати одночасно від ролі користувача, суми замовлення та промокоду."],"exercises":["Побудуй decision table для знижки за роллю, сумою та наявністю промокоду."]},"en":{"question":"When is a decision table useful?","answer":"When an outcome depends on combinations of conditions and business rules.","examples":["A discount may depend on the user role, order total, and promo code at the same time."],"exercises":["Build a decision table for a discount based on role, total, and promo code."]}}},{"id":"pairwise-limits","direction":"test-design","translations":{"uk":{"question":"Чи гарантує pairwise відсутність дефектів?","answer":"Ні. Він покриває пари значень факторів, але може пропустити взаємодії трьох і більше факторів.","examples":["Помилка може виникати лише для Safari, гостьового користувача та конкретної валюти разом."],"exercises":["Візьми чотири фактори checkout і поясни, який ризик залишиться після pairwise-набору."]},"en":{"question":"Does pairwise testing guarantee an absence of defects?","answer":"No. It covers pairs of factor values but may miss interactions among three or more factors.","examples":["A defect may occur only for Safari, a guest user, and one currency together."],"exercises":["Take four checkout factors and explain which risk remains after a pairwise set."]}}},{"id":"automation-priority","direction":"automation-architecture","translations":{"uk":{"question":"Що автоматизувати першочергово?","answer":"Стабільні, повторювані й ризикові сценарії з надійним oracle та прийнятною вартістю підтримки.","examples":["Критичний checkout із чітким API-результатом зазвичай кращий кандидат, ніж мінливий візуальний прототип."],"exercises":["Порівняй два сценарії за ризиком, повторюваністю, oracle і вартістю підтримки."]},"en":{"question":"What should be automated first?","answer":"Stable, repeatable, high-risk scenarios with a reliable oracle and acceptable maintenance cost.","examples":["A critical checkout with a clear API outcome is usually a better candidate than a changing visual prototype."],"exercises":["Compare two scenarios by risk, repeatability, oracle quality, and maintenance cost."]}}},{"id":"flaky-test","direction":"automation-architecture","translations":{"uk":{"question":"Що таке flaky test?","answer":"Це тест із нестабільним результатом за суттєво однакових умов; причина може бути в тесті, середовищі або продукті.","examples":["Тест іноді падає через гонку запитів, хоча код і тестові дані не змінювалися."],"exercises":["Для нестабільного тесту склади план збору evidence до додавання retry."]},"en":{"question":"What is a flaky test?","answer":"A test with unstable outcomes under materially identical conditions; the cause may be in the test, environment, or product.","examples":["A test sometimes fails because of a request race even though code and test data did not change."],"exercises":["For an unstable test, plan the evidence to collect before adding a retry."]}}},{"id":"automation-layers","direction":"automation-architecture","translations":{"uk":{"question":"Навіщо розділяти test logic і client/page layers?","answer":"Щоб сценарії описували поведінку, а деталі протоколів та UI змінювалися локально.","examples":["Зміна API endpoint має вимагати правки клієнта, а не кожного бізнес-сценарію."],"exercises":["Спроєктуй checkout: API setup → UI action → API assertion → cleanup і познач межі шарів."]},"en":{"question":"Why separate test logic from client and page layers?","answer":"So scenarios describe behaviour while protocol and UI details change locally.","examples":["An API endpoint change should require updating the client, not every business scenario."],"exercises":["Design a checkout flow—API setup, UI action, API assertion, cleanup—and mark the layer boundaries."]}}},{"id":"mutable-default","direction":"python-coding-whiteboard","translations":{"uk":{"question":"Чому mutable default argument небезпечний?","answer":"Default-об’єкт створюється під час визначення функції та повторно використовується між викликами.","examples":["Список за замовчуванням може зберегти елемент із попереднього виклику функції."],"exercises":["Напиши мінімальний приклад помилки й виправ його через значення None."]},"en":{"question":"Why is a mutable default argument dangerous?","answer":"The default object is created when the function is defined and reused across calls.","examples":["A default list may retain an item from a previous function call."],"exercises":["Write a minimal failing example and fix it by using None."]}}},{"id":"generator-vs-list","direction":"python-coding-whiteboard","translations":{"uk":{"question":"Чим generator відрізняється від list?","answer":"Generator видає значення поступово; list зберігає всі елементи. Generator зазвичай одноразовий і не підтримує довільний індексний доступ.","examples":["Потік великого файлу можна обробляти генератором без завантаження всіх рядків у пам’ять."],"exercises":["Реалізуй генератор читання даних пакетами й порівняй використання пам’яті зі списком."]},"en":{"question":"How does a generator differ from a list?","answer":"A generator yields values gradually; a list stores every item. A generator is usually single-use and has no arbitrary index access.","examples":["A large file can be streamed with a generator without loading every row into memory."],"exercises":["Implement batched data reading as a generator and compare memory use with a list."]}}},{"id":"asyncio-cpu","direction":"python-coding-whiteboard","translations":{"uk":{"question":"Чи прискорює asyncio CPU-heavy код?","answer":"Сам по собі — ні. Він корисний для конкурентного очікування I/O; CPU-heavy роботу слід планувати окремо.","examples":["Паралельне очікування HTTP-відповідей виграє від asyncio, а важке обчислення хешів блокує event loop."],"exercises":["Класифікуй п’ять задач як I/O-bound або CPU-bound і запропонуй модель виконання."]},"en":{"question":"Does asyncio speed up CPU-heavy code?","answer":"Not by itself. It helps with concurrent I/O waiting; CPU-heavy work needs a different execution strategy.","examples":["Waiting for HTTP responses can benefit from asyncio, while heavy hash calculation blocks the event loop."],"exercises":["Classify five tasks as I/O-bound or CPU-bound and propose an execution model."]}}},{"id":"isolated-browser-context","direction":"typescript-playwright-bdd","translations":{"uk":{"question":"Навіщо ізольований browser context?","answer":"Він розділяє cookies і browser state між тестами; backend-дані потрібно ізолювати окремо.","examples":["Два тести можуть мати окремі сесії браузера, але конфліктувати через спільний запис користувача в базі."],"exercises":["Запусти два сценарії паралельно та познач browser і backend state, які треба ізолювати."]},"en":{"question":"Why use an isolated browser context?","answer":"It separates cookies and browser state between tests; backend data must be isolated separately.","examples":["Two tests may have separate browser sessions but still collide on one user record in the database."],"exercises":["Run two scenarios in parallel and identify browser and backend state that must be isolated."]}}},{"id":"await-promises","direction":"typescript-playwright-bdd","translations":{"uk":{"question":"Чому await важливий?","answer":"Без очікування Promise наступна дія може початися до завершення попередньої, а помилка — залишитися поза потрібним обробником.","examples":["Клік без await може перетнутися з перевіркою навігації та створити гонку."],"exercises":["Знайди пропущений await у короткому тесті й поясни можливий порядок подій."]},"en":{"question":"Why is await important?","answer":"Without awaiting a Promise, the next action may start before the previous one finishes and an error may escape the intended handler.","examples":["A click without await may race with a navigation assertion."],"exercises":["Find a missing await in a short test and explain the possible event order."]}}},{"id":"gherkin-scope","direction":"typescript-playwright-bdd","translations":{"uk":{"question":"Що має описувати Gherkin?","answer":"Спостережувану бізнес-поведінку й очікуваний результат; дрібні технічні дії краще ховати в реалізації steps.","examples":["Крок «клієнт завершує оплату» стабільніший за перелік кожного CSS-селектора й кліку."],"exercises":["Опиши checkout у Gherkin і винеси API setup та технічні деталі в reusable steps."]},"en":{"question":"What should Gherkin describe?","answer":"Observable business behaviour and the expected outcome; small technical actions belong in step implementations.","examples":["A step such as “the customer completes payment” is more stable than listing every CSS selector and click."],"exercises":["Describe checkout in Gherkin and move API setup and technical details into reusable steps."]}}},{"id":"idempotent-method","direction":"web-http-networking","translations":{"uk":{"question":"Що означає idempotent method?","answer":"Кілька однакових запитів мають той самий очікуваний ефект на стан сервера, що й один. Відповіді можуть відрізнятися.","examples":["Повторний PUT того самого стану не створює ще один ресурс, хоча timestamp у відповіді може змінитися."],"exercises":["Перевір повторення PUT і сформулюй окремо очікування до стану та відповіді."]},"en":{"question":"What does an idempotent method mean?","answer":"Several identical requests have the same expected effect on server state as one request. Responses may differ.","examples":["Repeating a PUT for the same state does not create another resource, although a response timestamp may change."],"exercises":["Repeat a PUT and define separate expectations for state and response."]}}},{"id":"http-401-403","direction":"web-http-networking","translations":{"uk":{"question":"Чим 401 відрізняється від 403?","answer":"401 означає відсутність придатних authentication credentials; 403 — сервер зрозумів запит, але відмовляє в доступі.","examples":["Запит без токена отримує 401, а автентифікований користувач без потрібної ролі — 403."],"exercises":["Склади негативні API-перевірки для відсутнього, невалідного й недостатньо привілейованого токена."]},"en":{"question":"How does 401 differ from 403?","answer":"401 means suitable authentication credentials are missing; 403 means the server understood the request but refuses access.","examples":["A request without a token gets 401, while an authenticated user lacking the required role gets 403."],"exercises":["Design negative API checks for missing, invalid, and insufficiently privileged tokens."]}}},{"id":"cors","direction":"web-http-networking","translations":{"uk":{"question":"Що робить CORS?","answer":"Керує дозволом браузеру читати cross-origin responses; це не заміна серверної авторизації.","examples":["curl може прочитати відповідь, яку браузерний JavaScript блокує через CORS."],"exercises":["Порівняй той самий cross-origin запит у браузері та curl і досліди preflight."]},"en":{"question":"What does CORS do?","answer":"It controls whether a browser may read cross-origin responses; it does not replace server-side authorization.","examples":["curl may read a response that browser JavaScript blocks because of CORS."],"exercises":["Compare the same cross-origin request in a browser and curl, and inspect the preflight."]}}},{"id":"database-transaction","direction":"api-sql-data","translations":{"uk":{"question":"Навіщо транзакція?","answer":"Щоб пов’язані операції завершилися як одна логічна одиниця з commit або rollback.","examples":["Створення замовлення й резервування залишку мають або завершитися разом, або разом відкотитися."],"exercises":["Змоделюй помилку між двома SQL-операціями й перевір rollback."]},"en":{"question":"Why use a transaction?","answer":"So related operations complete as one logical unit with either commit or rollback.","examples":["Creating an order and reserving stock should either both complete or both roll back."],"exercises":["Simulate a failure between two SQL operations and verify the rollback."]}}},{"id":"database-index","direction":"api-sql-data","translations":{"uk":{"question":"Чому index не завжди прискорює систему?","answer":"Він може пришвидшити читання, але коштує місця та роботи під час запису; користь залежить від query plan і розподілу даних.","examples":["Індекс на низькоселективному полі може не використовуватися, але все одно сповільнювати вставки."],"exercises":["Порівняй EXPLAIN до й після індексу та виміряй вплив на читання і запис."]},"en":{"question":"Why does an index not always make a system faster?","answer":"It may speed up reads but costs storage and work on writes; value depends on the query plan and data distribution.","examples":["An index on a low-selectivity field may be ignored while still slowing inserts."],"exercises":["Compare EXPLAIN before and after an index, and measure its effect on reads and writes."]}}},{"id":"api-beyond-status","direction":"api-sql-data","translations":{"uk":{"question":"Що перевіряти крім HTTP status?","answer":"Схему й семантику response, зміни стану, авторизацію, побічні ефекти та поведінку повторного запиту.","examples":["201 не гарантує, що ресурс збережений правильно або подія була опублікована рівно один раз."],"exercises":["Для create endpoint склади перевірки контракту, стану, прав доступу, side effects та повтору."]},"en":{"question":"What should be checked beyond the HTTP status?","answer":"Response schema and semantics, state changes, authorization, side effects, and repeated-request behaviour.","examples":["A 201 does not prove that the resource was stored correctly or that an event was published exactly once."],"exercises":["For a create endpoint, design checks for contract, state, access, side effects, and retries."]}}},{"id":"continuous-delivery-deployment","direction":"cicd-docker-kubernetes","translations":{"uk":{"question":"Чим continuous delivery відрізняється від deployment?","answer":"Delivery підтримує готовність змін до випуску; deployment автоматично доставляє придатні зміни в production.","examples":["У delivery реліз може вимагати ручного рішення, тоді як deployment випускає успішну зміну автоматично."],"exercises":["Намалюй pipeline для обох моделей і познач місце людського approval."]},"en":{"question":"How does continuous delivery differ from continuous deployment?","answer":"Delivery keeps changes ready for release; deployment automatically releases suitable changes to production.","examples":["With delivery, release may require a human decision; deployment releases a successful change automatically."],"exercises":["Draw a pipeline for both models and mark the human approval point."]}}},{"id":"image-vs-container","direction":"cicd-docker-kubernetes","translations":{"uk":{"question":"Чим image відрізняється від container?","answer":"Image — шаблон файлової системи й конфігурації; container — його запущений або зупинений екземпляр із власним станом.","examples":["З одного immutable image можна запустити кілька контейнерів із різними змінними середовища."],"exercises":["Збери image, запусти два контейнери й порівняй їхню конфігурацію та writable state."]},"en":{"question":"How does an image differ from a container?","answer":"An image is a filesystem and configuration template; a container is its running or stopped instance with its own state.","examples":["One immutable image can start multiple containers with different environment variables."],"exercises":["Build an image, run two containers, and compare their configuration and writable state."]}}},{"id":"readiness-liveness","direction":"cicd-docker-kubernetes","translations":{"uk":{"question":"Чим readiness відрізняється від liveness?","answer":"Readiness визначає готовність приймати трафік; liveness — чи слід перезапустити контейнер через непрацездатність.","examples":["Під час warm-up pod може бути живим, але ще не готовим отримувати запити."],"exercises":["Спроєктуй окремі probes для сервісу, що довго прогріває cache."]},"en":{"question":"How does readiness differ from liveness?","answer":"Readiness decides whether a workload can receive traffic; liveness decides whether it should be restarted as unhealthy.","examples":["During warm-up, a pod may be alive but not ready to receive requests."],"exercises":["Design separate probes for a service with a long cache warm-up."]}}},{"id":"authentication-authorization","direction":"security-devsecops","translations":{"uk":{"question":"Чим authentication відрізняється від authorization?","answer":"Authentication встановлює, хто виконує дію; authorization визначає, чи дозволена йому конкретна дія над ресурсом.","examples":["Валідний користувач може увійти в систему, але не мати права читати чуже замовлення."],"exercises":["Негативно перевір доступ до чужого order у навчальному локальному середовищі."]},"en":{"question":"How does authentication differ from authorization?","answer":"Authentication establishes who performs an action; authorization decides whether that identity may act on a resource.","examples":["A valid user may sign in but still lack permission to read another user’s order."],"exercises":["Negatively test access to another user’s order in a local training environment."]}}},{"id":"sast-dast","direction":"security-devsecops","translations":{"uk":{"question":"Чому SAST і DAST доповнюють одне одного?","answer":"SAST аналізує код без запуску; DAST перевіряє поведінку запущеної системи. Обидва мають прогалини й false positives.","examples":["SAST бачить небезпечний data flow, а DAST — помилкову конфігурацію, що проявляється лише в runtime."],"exercises":["Для одного сервісу визнач findings, які очікуєш від SAST, DAST і ручної перевірки."]},"en":{"question":"Why do SAST and DAST complement each other?","answer":"SAST analyses code without running it; DAST tests a running system’s behaviour. Both have gaps and false positives.","examples":["SAST may see an unsafe data flow, while DAST finds a misconfiguration visible only at runtime."],"exercises":["For one service, identify findings expected from SAST, DAST, and manual review."]}}},{"id":"trust-boundary","direction":"security-devsecops","translations":{"uk":{"question":"Що таке trust boundary?","answer":"Межа між зонами з різними рівнями довіри, через яку проходять дані або керування.","examples":["Перехід від публічного API до внутрішньої черги потребує валідації, авторизації та аудиту."],"exercises":["Побудуй STRIDE для test server і познач усі trust boundaries."]},"en":{"question":"What is a trust boundary?","answer":"A boundary between zones with different trust levels through which data or control passes.","examples":["Moving from a public API to an internal queue requires validation, authorization, and auditing."],"exercises":["Build a STRIDE model for a test server and mark every trust boundary."]}}},{"id":"queue-long-runs","direction":"system-design-cloud","translations":{"uk":{"question":"Навіщо queue для довгих test runs?","answer":"Вона відділяє прийом задач від виконання й допомагає керувати навантаженням і workers; потрібні правила retries та duplicate handling.","examples":["API швидко приймає запуск, а workers забирають задачі відповідно до доступної місткості."],"exercises":["Спроєктуй Autotest Server із queue, workers і правилами повторної доставки."]},"en":{"question":"Why use a queue for long test runs?","answer":"It separates task intake from execution and helps manage load and workers; retry and duplicate-handling rules are still required.","examples":["An API accepts a run quickly while workers consume jobs according to available capacity."],"exercises":["Design an Autotest Server with a queue, workers, and redelivery rules."]}}},{"id":"rto-rpo","direction":"system-design-cloud","translations":{"uk":{"question":"Чим RTO відрізняється від RPO?","answer":"RTO — цільовий час відновлення; RPO — допустиме вікно втрати даних у часі.","examples":["RTO у 30 хвилин і RPO у 5 хвилин означають різні вимоги до відновлення сервісу та резервних копій."],"exercises":["Для evidence storage запропонуй RTO/RPO й поясни вартість вибору."]},"en":{"question":"How does RTO differ from RPO?","answer":"RTO is the target recovery time; RPO is the acceptable data-loss window measured in time.","examples":["An RTO of 30 minutes and RPO of 5 minutes create different service recovery and backup requirements."],"exercises":["Propose an RTO and RPO for evidence storage and explain the cost of your choice."]}}},{"id":"retry-outage","direction":"system-design-cloud","translations":{"uk":{"question":"Чому retries можуть погіршити outage?","answer":"Повторні спроби збільшують навантаження; потрібні ліміти, backoff, jitter і перевірка безпечності повторення.","examples":["Тисячі клієнтів із миттєвими retries можуть створити retry storm для вже перевантаженого сервісу."],"exercises":["Спроєктуй retry policy для нестабільного API та вкажи stop conditions."]},"en":{"question":"Why can retries make an outage worse?","answer":"Repeated attempts add load; they need limits, backoff, jitter, and a check that repetition is safe.","examples":["Thousands of clients retrying immediately can create a retry storm against an overloaded service."],"exercises":["Design a retry policy for an unstable API and define its stop conditions."]}}},{"id":"rag-purpose","direction":"ai-llm-rag-agents","translations":{"uk":{"question":"Що додає RAG до LLM?","answer":"RAG витягує релевантні зовнішні матеріали й додає їх у контекст генерації; це не гарантує правильність або повноту відповіді.","examples":["Асистент може відповісти за актуальною специфікацією, але все одно неправильно її інтерпретувати."],"exercises":["Порівняй відповіді з правильним, відсутнім і суперечливим retrieval-контекстом."]},"en":{"question":"What does RAG add to an LLM?","answer":"RAG retrieves relevant external material and adds it to the generation context; it does not guarantee a correct or complete answer.","examples":["An assistant may answer from a current specification and still interpret it incorrectly."],"exercises":["Compare answers with correct, missing, and conflicting retrieval context."]}}},{"id":"agent-not-needed","direction":"ai-llm-rag-agents","translations":{"uk":{"question":"Коли agent не потрібен?","answer":"Коли послідовність дій відома й може бути виконана звичайним workflow із чіткими правилами та validators.","examples":["Фіксований pipeline parse → validate → publish не потребує автономного вибору наступного кроку."],"exercises":["Перетвори один детермінований agent-сценарій на workflow і порівняй ризики."]},"en":{"question":"When is an agent unnecessary?","answer":"When the action sequence is known and a normal workflow with clear rules and validators can perform it.","examples":["A fixed parse, validate, then publish pipeline does not need autonomous next-step selection."],"exercises":["Convert one deterministic agent scenario into a workflow and compare the risks."]}}},{"id":"embeddings-permissions","direction":"ai-llm-rag-agents","translations":{"uk":{"question":"Чому embeddings не замінюють permissions?","answer":"Векторна схожість визначає релевантність; право доступу потрібно перевіряти окремо до передачі контексту моделі.","examples":["Семантично близький документ іншого клієнта не стає дозволеним джерелом."],"exercises":["Спроєктуй retrieval із фільтрацією tenant і перевір спробу cross-tenant доступу."]},"en":{"question":"Why do embeddings not replace permissions?","answer":"Vector similarity measures relevance; access must be checked separately before context reaches the model.","examples":["A semantically similar document belonging to another customer does not become an authorised source."],"exercises":["Design retrieval with tenant filtering and test a cross-tenant access attempt."]}}},{"id":"evaluation-vs-demo","direction":"llmops-evaluation-observability","translations":{"uk":{"question":"Чим evaluation відрізняється від одного demo?","answer":"Evaluation оцінює систему на наборі репрезентативних випадків за визначеними правилами; demo показує окремий сценарій.","examples":["Одна вдала відповідь не показує recall, стабільність або поведінку на edge cases."],"exercises":["Створи невеликий набір типових, негативних і граничних задач для одного LLM workflow."]},"en":{"question":"How does evaluation differ from a single demo?","answer":"Evaluation assesses a system on representative cases with defined rules; a demo shows one scenario.","examples":["One successful answer does not reveal recall, stability, or edge-case behaviour."],"exercises":["Create a small set of typical, negative, and boundary tasks for one LLM workflow."]}}},{"id":"llm-as-judge","direction":"llmops-evaluation-observability","translations":{"uk":{"question":"Чому LLM-as-judge не є абсолютним oracle?","answer":"Judge теж може помилятися й мати bias; його треба калібрувати на людських оцінках і доповнювати deterministic checks.","examples":["Judge може стабільно віддавати перевагу довшим відповідям незалежно від їх точності."],"exercises":["Порівняй оцінки judge з людською розміткою та знайди систематичні розбіжності."]},"en":{"question":"Why is LLM-as-judge not an absolute oracle?","answer":"The judge can also be wrong and biased; it needs calibration against human ratings and deterministic checks.","examples":["A judge may consistently prefer longer answers regardless of accuracy."],"exercises":["Compare judge scores with human labels and identify systematic disagreements."]}}},{"id":"traces-and-logs","direction":"llmops-evaluation-observability","translations":{"uk":{"question":"Навіщо traces поряд із logs?","answer":"Trace пов’язує кроки одного виконання й показує їх тривалість та залежності; logs фіксують окремі події.","examples":["Trace дозволяє побачити, що latency виникла в retrieval, а не під час model inference."],"exercises":["Для одного запиту визнач correlation id, spans, ключові events і поля, які не можна логувати."]},"en":{"question":"Why use traces alongside logs?","answer":"A trace connects the steps of one execution and shows timing and dependencies; logs record individual events.","examples":["A trace can reveal that latency came from retrieval rather than model inference."],"exercises":["For one request, define a correlation ID, spans, key events, and fields that must not be logged."]}}}]')},3118,e=>{"use strict";var t=e.i(7150),s=e.i(4555),i=e.i(2400);t.default;let a={Junior:0,Middle:1,Senior:2},n=[...s.default,...i.default];e.s(["getDirectionTranslation",0,function(e,t){return e.translations[t]??null},"getKnowledgeMaterials",0,function(e){return n.filter(t=>t.direction===e).sort((e,t)=>(e.level?a[e.level]:3)-(t.level?a[t.level]:3))},"getMaterialTranslation",0,function(e,t){return e.translations[t]??null}])}]);